   "在第(三)子題探討解任訴訟之構成要件時，或許題目未言明，少數應考人即假定該條件不存在，如起訴股東丁持股比例不足、解任議案未經股東會決議等，即逕否定丁不符合提起解任訴訟的要件，但如此未以其他可能情況探討要件是否該當，致使作答不完整。就甲卸任後再度當選法院得否解任甲的問題，因 B 公司為非公開發行股票公司，多數應考人認為可類推適用證券投資人及期貨交易人保護法（下稱投保法）第 10 條之 1 關於裁判解任訴訟的規定，或者，依該規定所揭示之法理，肯認法院仍可以裁判解任甲。惟本問題亦涉及董事卸任再就任，裁判解任訴訟是否能續行之問題。投保法引入董事失格制度後，董事即使卸任，不論是否再度當選，司法實務認為解任訴訟仍有訴訟利益。惟公司法之裁判解任訴訟並無失格效果，董、監事卸任後再度當選，該裁判解任訴訟是否有訴訟利益，似仍需討論，但僅有少數應考人有意識此一爭點。",
