   "但大部分對於第(二)子題保險代位與再保險之考點則答題狀況不佳。大部分考生都能先探討受僱人與保險法第 53 條第 2 項但書之適用，但或許因時間不夠或答題不夠謹慎而忽略本題主要仍在探討再保險契約如給付後，保險人對於第三人所得主張之權利，是否亦隨同移轉於再保險人？雖然本爭點近年來較少爭議，但過往不論實務判決或學說亦有不少討論，少數考生仍能區辨本題考點，成為高分關鍵。"
