   "二、審計委員會之會議規範，以及審計委員會全體成員之計算。",
   "三、證券交易法第 14 條之 5 審計委員會職權之規定，未經審計委員會全體成員二分之一以上同意或審計委員會無法召開時之處理，以及全體董事之計算。"
