   "幾乎所有應考人都會回答醫院與健保署的關係乃屬「健保契約」，但只有部",
   "分應考人有寫到其依據係釋字第 533 號解釋（內容），就評分而言，此一依據係",
   "屬重要。但子題中，另有二個「問號」，即須另以(一)(二)的方式回答：",
   "(一) 「違約記點」與「停約一個月」措施的性質：理論上認定「違約記點」與「停約一個月」應屬行政處分較容易著手，但針對「違約記點」與「停約一個月」，必須精確地寫到「確認停約一個月處分違法」之訴，此為重要考點，但多數應考人未回答到此一問題；另有少數應考人雖回答「確認處分」，但卻回答「確認行政契約仍屬有效」訴訟，應非良好的答案；但如果認為有「行政契約與行政處分禁止併用」原則，則必須主張此種救濟應提起「一般給付訴訟」，作此回答者，也有相應的分數。",
   "(二) 本小題應引據行政程序法第 110 條的「行政處分的存續力」，而以「記點三次」已具有「構成要件效力」作為論述「行政法院得不審查」，不是「不",
