   "此一問題在測驗應考人對「不予特約」法律性質的認識，大部分應考人並沒有將二種可能的模式列出，而係採取其中一種模式為作答依據，其固非錯誤，但缺乏整體性，總體評價不會太好。亦即，本題答案的模式宜為：就本問題，學理上有二說：",
