   "實務上專利法條文之具體適用雖常觸及技術觀點及技術判斷，但不論是第（一）子題或第（二）子題，均僅涉及專利法在法律上之最基本概念，第（一）子題甚而為契約屬性及契約約定內容之判斷。應考人若能掌握專利法之上開基本概念，進而涵攝至題目之事實及判斷、論述分析之，即能獲得高分。之之，若僅列出條文或僅寫出結論而無論述分析，僅能酌予給分。",
