   "針對第（二）子題，部分考生僅列出條文，不僅未區辨各該條文究竟是發明適格性或發明專利保護要件，亦未就其內容說明。另外，由於「Y 線上付款加密安全系統」涉及電腦程式或軟體、演算法（algorithm）之實施方式，少數考生就其發明適格性有採比較法觀點及論述外國立法例，例如：美國最高法院 2014年 Alice Corp. v. CLS Bank International 案及該案法院判決仍存有不同意見、歐洲國家對於電腦程式發明之保護，不論考生是依據比較法觀點而採何見解，只要有論述與分析，均予給分。再者，部分考生有進一步說明專利申請之程序要求，包括專利法第 26 規定之充分揭露、據以實現可能性等要求，同樣酌予給分。"
