   "為達成甲起訴「乙、丙」之目的，甲應更正及補充其聲明如下(或回答類似意旨，均酌予給分)：",
   "一、就先位聲明：確認被告乙就 X 地之所有權存在，被告丙塗銷 X 地（以買賣為原因）之所有權移轉登記。",
   "二、就備位聲明：撤銷被告「乙、丙」間 X 地之買賣契約（債權行為）及其所有權移轉契約（物權行為），被告丙塗銷 X 地（以買賣為原因）之所有權移轉",
   "登記。"
